WITH with_latest AS (SELECT s.*, x.order_item_quantity, x.order_item_unit_price FROM orders s LEFT JOIN LATERAL (SELECT c.quantity AS order_item_quantity, c.unit_price AS order_item_unit_price FROM order_items c WHERE c.order_id = s.id ORDER BY c.quantity DESC, c.id DESC LIMIT 1) x ON TRUE) SELECT DATE_TRUNC('QUARTER', order_date) AS quarter_start, SUM(discount) FILTER (WHERE status = 'RETURNED') AS returned_total_discount, COUNT(*) FILTER (WHERE status = 'RETURNED') AS returned_rows, SUM(CASE WHEN channel = 'web' THEN order_item_quantity ELSE 0 END) AS web_order_item_quantity, GROUPING(DATE_TRUNC('QUARTER', order_date)) AS gid FROM with_latest GROUP BY ROLLUP (DATE_TRUNC('QUARTER', order_date)) HAVING COUNT(*) FILTER (WHERE status = 'RETURNED') >= 1 ORDER BY quarter_start DESC NULLS LAST;
